import {makeData,TODAY,PROJECT,technicians,daysUntil,addDays,metrics} from './data.js?v=20260915-renovation';
import {e,num,money,date,icon,link,button,field,info,empty} from './ui.js?v=20260915-renovation';
import {renderPage} from './pages.js?v=20260915-renovation';
import {initializeRenovation} from './renovation-data.js?v=20260915-renovation';
import {renovationAction,renovationSubmit} from './renovation-controller.js?v=20260915-renovation';

function demoData(){const d=makeData();d.renovation=initializeRenovation(d);return d;}
let data=demoData(),guide=-1,toastTimer,searchTimer,lastFocus=null;
const app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
const nav=[['/','الرئيسية','grid'],['/overview','نظرة عامة على المشروع','layers'],['/buildings','المباني','building'],['/units','الوحدات السكنية','door'],['/applications','طلبات الإيجار','file-plus'],['/tenants','المستأجرون','users'],['/contracts','العقود','file'],['/payments','الدفعات','wallet'],['/maintenance','الصيانة','wrench'],['/renovation','التجديد والانتقال المؤقت','building'],['/reports','التقارير','chart'],['/roadmap','خطة التطوير','route']];
const guideStops=[['/overview','حجم المشروع','572 وحدة تحت إدارة واحدة'],['/value','المشكلة التشغيلية','من بيانات موزعة إلى منصة واحدة'],['/','لوحة الإدارة','حالة المشروع خلال دقيقة'],['/buildings','المباني والوحدات','من المبنى إلى تفاصيل الوحدة'],['/rental-journey','رحلة التأجير','من الطلب إلى تسليم المفاتيح'],['/tenants/TEN-2014','المستأجر والعقد','جميع التفاصيل في ملف 360°'],['/payments','تحصيل الإيجارات','من دفع؟ وما المتأخر؟'],['/maintenance/MNT-1025','إدارة الصيانة','المسؤول والحالة والخطوة التالية'],['/renovation','استمرارية التشغيل أثناء التجديد','انتقال مؤقت وخطة واضحة للعودة'],['/reports','مركز متابعة الإدارة','إشغال وتحصيل وصيانة'],['/value','القيمة التجارية','أثر تشغيلي مستهدف'],['/roadmap','خارطة التطوير','من العرض إلى منصة متكاملة']];
function route(){const raw=location.hash.slice(1)||'/';const [path,query='']=raw.split('?');return {path,q:new URLSearchParams(query)};}
function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
function render(){const {path,q}=route(),active=nav.find(([href])=>href==='/'?path==='/':path===href||path.startsWith(href+'/'))?.[0];const pageTitle=nav.find(([href])=>href===active)?.[1]||({'/rental-journey':'رحلة التأجير','/lifecycle':'دورة حياة الوحدة','/value':'القيمة المضافة'}[path])||'تفاصيل المعاملة';document.title=pageTitle+' | نواة';
 app.innerHTML=`<aside class="sidebar" aria-label="القائمة الرئيسية"><a class="brand" href="#/"><span class="brand-mark">${icon('building')}</span><div><strong>نواة</strong><small>NAWA PROPERTIES</small></div></a><nav class="nav"><div class="nav-label">مساحة العمل</div>${nav.map(([href,label,ico],i)=>`${i===10?'<div class="nav-label" style="margin-top:13px">الرؤية والمتابعة</div>':''}<a href="#${href}" class="${active===href?'active':''}" ${active===href?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${href==='/applications'?`<span class="nav-count">${data.applications.filter(a=>a.phase<2).length}</span>`:''}</a>`).join('')}<div class="nav-label" style="margin-top:13px">اكتشف التجربة</div>${[['/rental-journey','رحلة التأجير','key'],['/lifecycle','دورة حياة الوحدة','refresh'],['/value','القيمة المضافة','sparkles']].map(([h,t,i])=>link(h,icon(i)+`<span>${t}</span>`,path===h?'active':'')).join('')}</nav><div class="sidebar-bottom"><div class="demo-label"><span class="status-dot"></span>نموذج استثماري تفاعلي</div><p>بيانات توضيحية · نسخة العرض 01</p></div></aside>
 <div class="workspace"><header class="topbar"><div class="breadcrumb">${button(icon('menu'),'mobile-menu','icon-btn mobile-menu','aria-label="فتح القائمة" aria-expanded="false"')}<span>مساحة العمل</span>${icon('chevron')}<strong>${pageTitle}</strong></div><div class="top-actions"><form class="global-search" id="global-search">${icon('search')}<input name="search" placeholder="ابحث عن وحدة أو مستأجر..." aria-label="البحث في المشروع" autocomplete="off"/><kbd>/</kbd></form><span class="top-divider"></span>${button(icon('bell')+'<span class="notification-dot"></span>','attention','icon-btn','aria-label="الإجراءات التي تحتاج متابعة"')}<span class="top-divider"></span><div class="user-info"><span class="avatar">م س</span><div><strong>محمد السالم</strong><small>مدير المشروع</small></div></div>${button(icon('down'),'demo-menu','icon-btn','aria-label="خيارات العرض"')}</div></header><main class="main" id="main" tabindex="-1">${renderPage(data,path,q)}<footer class="footer"><span>${icon('shield')} نواة · إدارة وتشغيل العقارات</span><span>بيانات تجريبية محلية · ${date(TODAY)}</span></footer>${guide>=0?guideBar():''}</main></div>`;
}
function guideBar(){const s=guideStops[guide];return `<section class="guide-bar" aria-label="العرض الاستثماري الموجه"><div style="display:flex;align-items:center;gap:12px">${button(icon('close'),'stop-guide','icon-btn','aria-label="إنهاء العرض الموجه"')}<div><small>العرض الاستثماري · ${guide+1} من ${guideStops.length}</small><strong>${s[1]} — ${s[2]}</strong></div></div><div class="guide-dots">${guideStops.map((_,i)=>`<span class="${i===guide?'active':''}"></span>`).join('')}</div><div class="heading-actions">${guide>0?button(icon('chevron'),'prev-guide','icon-btn','aria-label="الخطوة السابقة في العرض"'):''}${button((guide===guideStops.length-1?'إنهاء العرض':'التالي')+' '+icon('left'),'next-guide','btn')}</div></section>`;}
function filter(key,value){const {path,q}=route();if(!value||value==='ALL')q.delete(key);else q.set(key,value);if(key!=='page')q.delete('page');go(path+(q.toString()?'?'+q.toString():''));}
function toast(message){clearTimeout(toastTimer);document.querySelector('#toast-root').innerHTML=`<div class="toast">${icon('check')}<span>${e(message)}</span></div>`;toastTimer=setTimeout(()=>document.querySelector('#toast-root').innerHTML='',4500);}
function openModal(title,body,form='',submit='حفظ',wide=false){lastFocus=document.activeElement;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-header"><h2 id="modal-title">${title}</h2>${button(icon('close'),'close-modal','icon-btn','aria-label="إغلاق النافذة"')}</div>${form?`<form id="${form}">`:''}<div class="modal-body">${body}<p id="form-error" class="form-error" role="alert"></p></div>${form?`<div class="modal-footer"><button class="btn primary" type="submit">${submit}</button>${button('إلغاء','close-modal','btn','type="button"')}</div></form>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>modalRoot.querySelector('input,select,textarea,.modal .btn,.modal .icon-btn')?.focus(),0);}
function closeModal(){modalRoot.innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus();}
function error(message){document.querySelector('#form-error').textContent=message;}
function hidden(name,value){return `<input type="hidden" name="${name}" value="${e(value)}"/>`;}
const inp=(name,value='',attrs='')=>`<input name="${name}" value="${e(value)}" ${attrs}/>`;
function select(name,options,selected='',attrs=''){return `<select name="${name}" ${attrs}>${options.map(([v,t])=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(t)}</option>`).join('')}</select>`;}
function activity(text,detail,href,ico='check'){data.activities.unshift({text,detail,href,icon:ico,tone:'green',time:'الآن'});}
function refreshWithToast(msg){closeModal();render();toast(msg);}
function newApplication(unitId=''){const u=data.units.find(u=>u.id===unitId);openModal('طلب إيجار جديد',`<p class="modal-description">أدخل بيانات العميل لبدء رحلة التأجير. تُحفظ التغييرات داخل جلسة العرض فقط.</p>${hidden('unitId',u?.id||'')}<div class="form-grid">${field('اسم العميل *',inp('name','','required maxlength="70" placeholder="الاسم الكامل"'))}${field('رقم الجوال *',inp('mobile','','required type="tel" dir="ltr" pattern="05[0-9]{8}" placeholder="05xxxxxxxx" maxlength="10"'))}${field('نوع الوحدة',select('bedrooms',[['2','غرفتا نوم'],['1','غرفة نوم']],String(u?.bedrooms||2)))}${field('عدد أفراد الأسرة',inp('family','4','type="number" min="1" max="20" required'))}${field('الميزانية السنوية (ر.س)',inp('budget',u?.rent||36000,'type="number" min="1000" max="500000" step="100" required'))}${field('موعد الانتقال المتوقع',inp('moveDate','2026-10-01',`type="date" min="${TODAY}" required`))}${u?field('الوحدة المرغوبة',inp('unitLabel',u.id,'readonly')):''}${field('ملاحظات',`<textarea name="notes" maxlength="500" placeholder="تفضيلات العميل أو معلومات إضافية"></textarea>`,true)}</div>`,'new-application-form','إنشاء الطلب');}
function paymentModal(id){const p=data.payments.find(x=>x.id===id);if(!p||p.paid>=p.amount)return toast('تم تحصيل هذه الدفعة بالكامل.');const t=data.tenants.find(x=>x.id===p.tenantId);openModal('تسجيل دفعة',`<div class="confirmation">${icon('wallet')}<div><strong>${e(t?.name)} · <span class="ltr">${p.unitId}</span></strong><p>المتبقي على الدفعة: ${money(p.amount-p.paid)}</p></div></div>${hidden('paymentId',id)}<div class="form-grid">${field('المبلغ (ر.س) *',inp('amount',p.amount-p.paid,`type="number" min="0.01" max="${p.amount-p.paid}" step="0.01" required`))}${field('تاريخ الدفع',inp('paidAt',TODAY,`type="date" max="${TODAY}" required`))}${field('طريقة الدفع',select('method',[['تحويل بنكي','تحويل بنكي'],['نقد','نقد'],['بطاقة','بطاقة'],['أخرى','أخرى']]))}${field('الرقم المرجعي',inp('reference','','maxlength="50" placeholder="رقم العملية"'))}${field('ملاحظات',`<textarea name="notes" maxlength="300" placeholder="ملاحظة اختيارية"></textarea>`,true)}</div>`,'payment-form','تأكيد تسجيل الدفعة');}
function rentalNext(id){const a=data.applications.find(x=>x.id===id);if(!a)return;
 if(a.phase===0||a.phase===1){openModal(a.phase===0?'بدء مراجعة الطلب':'اعتماد طلب الإيجار',`<div class="confirmation">${icon(a.phase===0?'file':'check')}<div><strong>${e(a.name)}</strong><p>${a.bedrooms===2?'غرفتا نوم':'غرفة نوم'} · ميزانية ${money(a.budget)}</p></div></div><p class="small muted">${a.phase===0?'سينتقل الطلب إلى المراجعة لتأكيد ملاءمة الوحدة لاحتياج العميل.':'عند الاعتماد، ستكون الخطوة التالية اختيار وحدة شاغرة وحجزها للعميل.'}</p>${hidden('id',id)}`,'rental-advance-form',a.phase===0?'بدء المراجعة':'اعتماد الطلب');}
 if(a.phase===2){const us=data.units.filter(u=>u.status==='VACANT'&&u.usageType==='RENTAL'&&u.bedrooms===a.bedrooms);openModal('اختيار وحجز الوحدة',`<p class="modal-description">الوحدات المتاحة المطابقة لطلب ${e(a.name)}. بعد الحجز تصبح الوحدة محجوزة داخل العرض.</p>${hidden('id',id)}${field('الوحدة المتاحة *',select('unitId',us.map(u=>[u.id,`${u.id} · ${u.bedrooms===2?'غرفتا نوم':'غرفة نوم'} · ${num(u.rent)} ر.س / سنة`]),a.unitId||us[0]?.id,'required'))}`,'reserve-form','تأكيد حجز الوحدة');}
 if(a.phase===3){const u=data.units.find(x=>x.id===a.unitId);openModal('إنشاء عقد الإيجار',`<div class="confirmation">${icon('file')}<div><strong>${e(a.name)}</strong><p>الوحدة المحجوزة: <span class="ltr">${u.id}</span></p></div></div>${hidden('id',id)}<div class="form-grid">${field('بداية العقد',inp('start','2026-10-01',`type="date" min="${TODAY}" required`))}${field('مدة العقد',inp('term','سنة واحدة','readonly'))}${field('قيمة الإيجار السنوي (ر.س)',inp('amount',u.rent,'type="number" min="1000" max="500000" step="1" required'))}${field('جدول الدفعات',inp('schedule','3 دفعات متساوية','readonly'))}</div><p class="small muted" style="margin-top:17px">ستُنشأ بطاقة المستأجر والعقد وجدول الدفعات محلياً. الخطوة التالية: استلام الدفعة الأولى.</p>`,'contract-form','إنشاء العقد');}
 if(a.phase===4){const p=data.payments.find(p=>p.contractId===a.contractId&&p.paid<p.amount);if(p)paymentModal(p.id);else{a.phase=5;render();}}
 if(a.phase===5){openModal('تسليم الوحدة',`<div class="confirmation">${icon('key')}<div><strong>جاهزة للتسليم · <span class="ltr">${a.unitId}</span></strong><p>تم إنشاء العقد واستلام الدفعة الأولى.</p></div></div>${hidden('id',id)}<label style="display:flex;align-items:center;gap:10px;font-size:13px"><input type="checkbox" required name="keys"/>تم فحص الوحدة وتسليم المفاتيح للمستأجر.</label><p class="small muted" style="margin-top:14px">عند التأكيد، تتحول حالة الوحدة إلى «مؤجرة» وتتحدث مؤشرات المشروع.</p>`,'handover-form','تأكيد تسليم الوحدة');}
}
function newMaintenance(unitId=''){const us=data.units;openModal('طلب صيانة جديد',`<p class="modal-description">بلاغ واضح يساعد الفريق على تحديد الأولوية وتعيين الفني المناسب.</p><div class="form-grid">${field('الوحدة *',select('unitId',us.map(u=>[u.id,u.id+(u.tenantId?' · '+data.tenants.find(t=>t.id===u.tenantId)?.name:' · شاغرة')]),unitId||'A01-204','required'))}${field('نوع المشكلة',select('type',['سباكة','كهرباء','تكييف','مصاعد','أبواب','أعمال مدنية','نظافة','أخرى'].map(x=>[x,x])))}${field('عنوان البلاغ *',inp('issue','','required maxlength="90" placeholder="مثال: تسرب مياه في المطبخ"'),true)}${field('الأولوية',select('priority',[['NORMAL','عادي'],['HIGH','عالي'],['EMERGENCY','طارئ'],['LOW','منخفض']]))}${field('وصف المشكلة *',`<textarea name="description" required minlength="5" maxlength="700" placeholder="أين المشكلة؟ ومتى بدأت؟"></textarea>`,true)}</div>`,'new-maintenance-form','إرسال البلاغ');}
function maintenanceNext(id){const m=data.maintenance.find(x=>x.id===id);if(!m)return;
 if(m.waiting){m.waiting=false;m.phase=4;m.history.push({time:'الآن',text:'توفرت القطع واستؤنف العمل',by:technicians.find(t=>t.id===m.technicianId)?.name});render();toast('تم استئناف العمل على البلاغ.');return;}
 if(m.phase===2){openModal('تعيين الفني المسؤول',`${hidden('id',id)}<p class="modal-description">البلاغ ${id} · ${e(m.type)}</p>${field('الفني *',select('technicianId',technicians.map(t=>[t.id,t.name+' · '+t.specialty]),'','required'))}`,'assign-form','تعيين الفني');return;}
 if(m.phase===4){openModal('توثيق تنفيذ الإصلاح',`${hidden('id',id)}<p class="modal-description">سجل ما تم عمله قبل إرسال البلاغ لفحص التنفيذ.</p>${field('الأعمال المنفذة *',`<textarea name="notes" required minlength="10" maxlength="800" placeholder="اكتب تفاصيل الإصلاح ونتيجة الفحص الأولي..."></textarea>`)}`,'work-form','حفظ تقرير العمل');return;}
 const labels={0:'تأكيد مراجعة البلاغ',1:'تأكيد أولوية البلاغ',3:'تأكيد بدء العمل',5:'إرسال الطلب لفحص التنفيذ',6:'اعتماد التنفيذ وإغلاق البلاغ'};
 openModal(labels[m.phase],`${hidden('id',id)}<div class="confirmation">${icon('wrench')}<div><strong>${e(m.issue)}</strong><p>${m.id} · ${m.unitId}</p></div></div>${m.phase===1?field('الأولوية',select('priority',[['LOW','منخفض'],['NORMAL','عادي'],['HIGH','عالي'],['EMERGENCY','طارئ']],m.priority)):`<p class="small muted">${m.phase===6?'يؤكد مشرف الصيانة جودة الإصلاح، ثم يغلق البلاغ ويحدّث مؤشرات المتابعة.':'سيتقدم البلاغ إلى المرحلة التالية ويُضاف الإجراء إلى السجل.'}</p>`}`,'maintenance-advance-form',labels[m.phase]);
}
function showSearch(term){const q=term.trim().toLowerCase();const us=data.units.filter(u=>u.id.toLowerCase().includes(q)).slice(0,5),ts=data.tenants.filter(t=>t.name.includes(q)).slice(0,5),as=data.applications.filter(a=>(a.id+' '+a.name).toLowerCase().includes(q)).slice(0,4);openModal('نتائج البحث',`<p class="modal-description">نتائج «${e(term)}» في المشروع</p><div class="search-results">${[...us.map(u=>link('/units/'+u.id,`<span class="icon-box">${icon('door')}</span><div><strong class="ltr">${u.id}</strong><small>وحدة سكنية · ${u.bedrooms===2?'غرفتا نوم':'غرفة نوم'}</small></div>`)),...ts.map(t=>link('/tenants/'+t.id,`<span class="icon-box">${icon('users')}</span><div><strong>${e(t.name)}</strong><small>${t.unitId} · ملف المستأجر</small></div>`)),...as.map(a=>link('/applications/'+a.id,`<span class="icon-box">${icon('file-plus')}</span><div><strong>${e(a.name)}</strong><small>${a.id} · طلب إيجار</small></div>`))].join('')||empty('لا توجد نتائج','جرّب رقم وحدة مثل A01-204 أو اسم مستأجر.')}</div>`);}
function exportCsv(name,rows){const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('تم تصدير البيانات التجريبية.');}
function renovationContext(){return {data,openModal,toast,render,error,activity,refreshWithToast};}
function perform(action,id,target){
 if(renovationAction(action,id,renovationContext()))return;
 if(action==='close-modal')return closeModal();
 if(action==='mobile-menu'){const side=document.querySelector('.sidebar');const open=side.classList.toggle('open');target.setAttribute('aria-expanded',String(open));document.querySelector('.sidebar-scrim')?.remove();if(open){const scrim=document.createElement('div');scrim.className='sidebar-scrim';scrim.dataset.action='close-nav';app.prepend(scrim);}return;}
 if(action==='close-nav'){document.querySelector('.sidebar')?.classList.remove('open');document.querySelector('.sidebar-scrim')?.remove();document.querySelector('[data-action="mobile-menu"]')?.setAttribute('aria-expanded','false');return;}
 if(action==='filter')return filter(target.dataset.key,target.dataset.value);
 if(action==='page')return filter('page',target.dataset.page);
 if(action==='start-guide'||action==='restart-guide'){guide=0;go(guideStops[0][0]);return;}
 if(action==='stop-guide'){guide=-1;render();return;}
 if(action==='next-guide'){if(guide<guideStops.length-1){guide++;go(guideStops[guide][0]);}else{guide=-1;render();toast('اكتمل العرض الاستثماري. يمكنك استكشاف المنصة بحرية.');}return;}
 if(action==='prev-guide'){guide=Math.max(0,guide-1);go(guideStops[guide][0]);return;}
 if(action==='new-application')return newApplication(id);
 if(action==='rental-next')return rentalNext(id);
 if(action==='payment')return paymentModal(id);
 if(action==='tenant-payment'){const p=data.payments.find(p=>p.tenantId===id&&p.paid<p.amount);return p?paymentModal(p.id):toast('جميع دفعات المستأجر مكتملة.');}
 if(action==='choose-payment'){const ps=data.payments.filter(p=>p.paid<p.amount);openModal('اختيار الدفعة',`<p class="modal-description">اختر المستأجر والدفعة المطلوب تحصيلها.</p>${field('الدفعة المستحقة',select('paymentId',ps.map(p=>[p.id,`${data.tenants.find(t=>t.id===p.tenantId)?.name} · ${p.unitId} · ${num(p.amount-p.paid)} ر.س · ${p.due}`]),'','required'))}`,'choose-payment-form','متابعة');return;}
 if(action==='receipt'){const p=data.payments.find(p=>p.id===id);openModal('سجل التحصيل',info([['رقم الدفعة',p.id],['المستأجر',e(data.tenants.find(t=>t.id===p.tenantId)?.name)],['الوحدة',p.unitId],['المبلغ المحصّل',money(p.paid)],['آخر تاريخ دفع',date(p.paidAt)],['طريقة الدفع',e(p.method)]])+`<p class="small muted">سجل توضيحي ضمن العرض الاستثماري.</p>`);return;}
 if(action==='new-maintenance')return newMaintenance(id);
 if(action==='maintenance-next')return maintenanceNext(id);
 if(action==='wait-parts'){const m=data.maintenance.find(m=>m.id===id);m.waiting=true;m.history.push({time:'الآن',text:'العمل بانتظار توفر قطع الغيار',by:'الفني المسؤول'});render();toast('تم تحديث البلاغ إلى بانتظار قطع غيار.');return;}
 if(action==='attention'){const m=metrics(data);openModal('يحتاج متابعة اليوم',`<div class="search-results">${link('/payments?status=OVERDUE',`<span class="icon-box amber">${icon('wallet')}</span><div><strong>${money(m.overdue)} متأخرات</strong><small>${m.overdueCount} دفعة تحتاج متابعة</small></div>`)}${link('/maintenance?priority=EMERGENCY',`<span class="icon-box red">${icon('alert')}</span><div><strong>${m.emergency} بلاغات صيانة طارئة</strong><small>عرض المسؤول والمرحلة التالية</small></div>`)}${link('/contracts?window=30',`<span class="icon-box blue">${icon('calendar')}</span><div><strong>عقود تنتهي خلال 30 يوماً</strong><small>ابدأ متابعة التجديد أو الإخلاء</small></div>`)}</div>`);return;}
 if(action==='activity'){openModal('سجل الأنشطة',`<div class="search-results">${data.activities.map(a=>link(a.href,`<span class="icon-box">${icon(a.icon)}</span><div><strong>${e(a.text)}</strong><small>${e(a.detail)} · ${a.time}</small></div>`)).join('')}</div>`);return;}
 if(action==='demo-menu'){openModal('خيارات العرض',`<p class="modal-description">هذا نموذج استثماري تفاعلي. التغييرات محلية وتعود البيانات إلى البداية عند تحديث الصفحة.</p><div class="modal-quick-links">${link('/overview',icon('layers')+'نظرة عامة على المشروع')}${link('/roadmap',icon('route')+'خطة التطوير')}</div><div class="heading-actions" style="margin-top:20px">${button(icon('play')+' بدء العرض الموجه','start-guide','btn primary')}${button(icon('refresh')+' إعادة ضبط البيانات','reset','btn')}</div>`);return;}
 if(action==='reset'){openModal('إعادة ضبط العرض',`<p class="small muted">ستُعاد جميع التغييرات التجريبية إلى بيانات البداية، بما فيها الحجوزات والدفعات والبلاغات التي أضفتها في هذه الجلسة.</p>`,'reset-form','إعادة ضبط البيانات');return;}
 if(action==='renew'){const c=data.contracts.find(c=>c.id===id);openModal('تجديد العقد',`${hidden('id',id)}<div class="confirmation">${icon('calendar')}<div><strong>${e(data.tenants.find(t=>t.id===c.tenantId)?.name)}</strong><p>العقد الحالي ينتهي في ${date(c.end)}</p></div></div>${field('نهاية العقد بعد التمديد',inp('end',addDays(c.end,365),`type="date" min="${addDays(c.end,1)}" required`))}<p class="small muted" style="margin-top:15px">محاكاة تمديد مدة العقد لتوضيح متابعة التجديد. جدول الدفعات في هذه التجربة يبقى كما هو.</p>`,'renew-form','تأكيد التمديد التجريبي');return;}
 if(action==='move-out'){openModal('رحلة إخلاء الوحدة',`<p class="modal-description">إجراء تشغيلي ضمن دورة حياة الوحدة، يبدأ بعد قرار عدم التجديد.</p><div class="step-group">${['إشعار انتهاء العقد','طلب إخلاء','فحص الوحدة','تسجيل الملاحظات والأضرار','تسوية الالتزامات المالية','استلام المفاتيح','إغلاق العقد','شاغرة أو تحت الصيانة'].map((s,i)=>`<span>${i+1}. ${s}</span>`).join('')}</div><div class="next-action"><div><p>المسؤول: فريق التشغيل</p><h3>الخطوة الأولى: تنسيق موعد الفحص</h3></div></div><p class="small muted">عرض توضيحي لمسار الإخلاء. لا يُغلق العقد أو تُسوى مبالغ فعلية من هذه النافذة.</p>${link('/lifecycle','استكشف دورة حياة الوحدة '+icon('left'),'btn primary')}`);return;}
 if(action==='print')return window.print();
 if(action==='export-report'){const m=metrics(data);return exportCsv('nawa-executive-report',[['التقرير','نموذج استثماري - '+TODAY],['المشروع',PROJECT],['إجمالي الوحدات',m.total],['مؤجرة',m.occupied],['شاغرة',m.vacant],['محجوزة',m.reserved],['تحت الصيانة',m.underMaintenance],['نسبة الإشغال',num(m.occupancy,1)+'%'],['المستحقات',m.amount],['المحصّل',m.paid],['المتأخرات',m.overdue],['الصيانة المفتوحة',m.open],['الصيانة الطارئة',m.emergency]]);}
 if(action==='export-payments')return exportCsv('nawa-payments',[['المستأجر','الوحدة','العقد','المبلغ','المدفوع','المتبقي','الاستحقاق'],...data.payments.map(p=>[data.tenants.find(t=>t.id===p.tenantId)?.name,p.unitId,p.contractId,p.amount,p.paid,p.amount-p.paid,p.due])]);
}
document.addEventListener('click',ev=>{if(ev.target.closest('.skip-link')){ev.preventDefault();document.querySelector('#main')?.focus();return;}const target=ev.target.closest('[data-action]');if(target){ev.preventDefault();const action=target.dataset.action;if(['start-guide','restart-guide'].includes(action))closeModal();perform(action,target.dataset.id||'',target);}else if(ev.target===modalRoot.querySelector('.modal-backdrop'))closeModal();else if(ev.target.closest('#modal-root a[href^="#"]'))closeModal();});
document.addEventListener('change',ev=>{if(ev.target.dataset.filter)filter(ev.target.dataset.filter,ev.target.value);});
document.addEventListener('input',ev=>{if(ev.target.dataset.search){clearTimeout(searchTimer);const value=ev.target.value,key=ev.target.dataset.search;searchTimer=setTimeout(()=>{const {path,q}=route();q.set(key,value);q.delete('page');history.replaceState(null,'','#'+path+'?'+q.toString());render();const input=document.querySelector('[data-search="'+key+'"]');input?.focus();},180);}});
document.addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target,values=Object.fromEntries(new FormData(form));
 if(renovationSubmit(form.getAttribute('id'),values,renovationContext()))return;
 if(form.getAttribute('id')==='global-search'){if(values.search.trim())showSearch(values.search);return;}
 if(form.getAttribute('id')==='new-application-form'){if(!values.name.trim())return error('أدخل اسم العميل.');const id='REQ-'+(Math.max(...data.applications.map(a=>Number(a.id.split('-')[1])))+1);data.applications.unshift({id,name:values.name.trim(),mobile:values.mobile,bedrooms:Number(values.bedrooms),date:TODAY,phase:0,unitId:values.unitId,family:Number(values.family),budget:Number(values.budget),notes:values.notes,history:[{text:'تم إنشاء طلب الإيجار',date:TODAY,by:'محمد السالم'}]});activity('طلب إيجار جديد من '+values.name,'الطلب '+id,'/applications/'+id,'file-plus');closeModal();go('/applications/'+id);toast('تم إنشاء طلب الإيجار بنجاح.');return;}
 if(form.getAttribute('id')==='rental-advance-form'){const a=data.applications.find(a=>a.id===values.id);a.phase++;a.history.push({text:a.phase===1?'بدأت مراجعة بيانات العميل':'تم اعتماد طلب الإيجار',date:TODAY,by:'محمد السالم'});activity(a.phase===1?'بدء مراجعة طلب '+a.id:'تم اعتماد طلب '+a.id,a.name,'/applications/'+a.id,'file-plus');return refreshWithToast(a.phase===1?'الطلب الآن تحت المراجعة.':'تم اعتماد طلب الإيجار بنجاح.');}
 if(form.getAttribute('id')==='reserve-form'){const a=data.applications.find(a=>a.id===values.id),u=data.units.find(u=>u.id===values.unitId);if(!u||u.status!=='VACANT'||u.usageType!=='RENTAL')return error('اختر وحدة شاغرة متاحة.');u.status='RESERVED';a.unitId=u.id;a.phase=3;a.history.push({text:'تم حجز الوحدة '+u.id,date:TODAY,by:'مسؤول التأجير'});activity('تم حجز الوحدة '+u.id,a.name,'/applications/'+a.id,'key');return refreshWithToast('تم حجز الوحدة، الخطوة التالية إنشاء العقد.');}
 if(form.getAttribute('id')==='contract-form'){const a=data.applications.find(a=>a.id===values.id),u=data.units.find(u=>u.id===a.unitId);if(!u||u.status!=='RESERVED')return error('يجب حجز الوحدة قبل إنشاء العقد.');const tid='TEN-'+(Math.max(...data.tenants.map(t=>Number(t.id.split('-')[1])))+1),cid='CON-'+(Math.max(...data.contracts.map(c=>Number(c.id.split('-')[1])))+1),amount=Number(values.amount);if(!Number.isFinite(amount)||amount<1000)return error('أدخل قيمة عقد صحيحة.');const c={id:cid,tenantId:tid,unitId:u.id,start:values.start,end:addDays(values.start,365),amount,status:'ACTIVE'};data.contracts.unshift(c);data.tenants.unshift({id:tid,name:a.name,mobile:a.mobile,nationality:'غير محدد',family:a.family,unitId:u.id,contractId:cid,email:'—',joined:values.start,notes:a.notes});u.tenantId=tid;u.contractId=cid;u.rent=amount;a.contractId=cid;a.phase=4;const first=Math.round(amount/3);for(let n=0;n<3;n++){const pid='PAY-'+(Math.max(...data.payments.map(p=>Number(p.id.split('-')[1])))+1);data.payments.push({id:pid,contractId:cid,tenantId:tid,unitId:u.id,amount:n===2?amount-2*first:first,paid:0,due:addDays(values.start,n*120),paidAt:null,method:'—'});}a.history.push({text:'تم إنشاء العقد '+cid,date:TODAY,by:'مسؤول العقود'});activity('تم إنشاء عقد للوحدة '+u.id,a.name,'/contracts/'+cid,'file');return refreshWithToast('تم إنشاء العقد وجدول الدفعات محلياً.');}
 if(form.getAttribute('id')==='choose-payment-form'){closeModal();return paymentModal(values.paymentId);}
 if(form.getAttribute('id')==='payment-form'){const p=data.payments.find(p=>p.id===values.paymentId),amount=Number(values.amount);if(!p||!Number.isFinite(amount)||amount<=0||amount>p.amount-p.paid)return error('المبلغ يجب أن يكون أكبر من صفر ولا يتجاوز المتبقي.');p.paid=Math.round((p.paid+amount)*100)/100;p.paidAt=values.paidAt;p.method=values.method;p.reference=values.reference;p.notes=values.notes;const a=data.applications.find(a=>a.contractId===p.contractId&&a.phase===4);if(a&&p.paid>=p.amount){a.phase=5;a.history.push({text:'تم استلام الدفعة الأولى',date:TODAY,by:'قسم التحصيل'});}activity('تم استلام دفعة للوحدة '+p.unitId,num(amount)+' ر.س · '+p.method,'/tenants/'+p.tenantId,'wallet');return refreshWithToast('تم تسجيل الدفعة وتحديث رصيد المستأجر.');}
 if(form.getAttribute('id')==='handover-form'){const a=data.applications.find(a=>a.id===values.id),u=data.units.find(u=>u.id===a.unitId);if(a.phase!==5)return error('أكمل الدفعة الأولى قبل التسليم.');a.phase=6;u.status='OCCUPIED';a.history.push({text:'تم تسليم المفاتيح وتحويل الوحدة إلى مؤجرة',date:TODAY,by:'فريق التشغيل'});activity('تم تسليم الوحدة '+u.id,a.name,'/units/'+u.id,'key');return refreshWithToast('تم تسليم الوحدة بنجاح وتحديث نسبة الإشغال.');}
 if(form.getAttribute('id')==='new-maintenance-form'){const u=data.units.find(u=>u.id===values.unitId);if(!values.issue.trim()||!values.description.trim())return error('أدخل عنوان المشكلة ووصفها.');const id='MNT-'+(Math.max(...data.maintenance.map(m=>Number(m.id.split('-')[1])))+1);data.maintenance.unshift({id,unitId:u.id,tenantId:u.tenantId,issue:values.issue.trim(),type:values.type,description:values.description.trim(),priority:values.priority,technicianId:'',phase:0,waiting:false,date:TODAY,notes:'',history:[{time:'الآن',text:'تم استلام البلاغ',by:'محمد السالم'}]});activity('تم إنشاء بلاغ الصيانة '+id,u.id+' · '+values.type,'/maintenance/'+id,'wrench');closeModal();go('/maintenance/'+id);toast('تم إنشاء بلاغ الصيانة بنجاح.');return;}
 if(form.getAttribute('id')==='assign-form'){const m=data.maintenance.find(m=>m.id===values.id);m.technicianId=values.technicianId;m.phase=3;m.history.push({time:'الآن',text:'تم تعيين الفني',by:technicians.find(t=>t.id===m.technicianId).name});return refreshWithToast('تم تعيين الفني المسؤول.');}
 if(form.getAttribute('id')==='work-form'){if(values.notes.trim().length<10)return error('أضف وصفاً واضحاً للأعمال المنفذة.');const m=data.maintenance.find(m=>m.id===values.id);m.notes=values.notes.trim();m.phase=5;m.history.push({time:'الآن',text:'تم توثيق أعمال الإصلاح',by:technicians.find(t=>t.id===m.technicianId)?.name});return refreshWithToast('تم حفظ تقرير الإصلاح، الخطوة التالية فحص التنفيذ.');}
 if(form.getAttribute('id')==='maintenance-advance-form'){const m=data.maintenance.find(m=>m.id===values.id);if(values.priority)m.priority=values.priority;m.phase++;const messages={1:'تمت مراجعة البلاغ',2:'تم تأكيد أولوية البلاغ',4:'بدأ الفني العمل',6:'تم إرسال البلاغ لفحص التنفيذ',7:'تم اعتماد الإصلاح وإغلاق البلاغ'};m.history.push({time:'الآن',text:messages[m.phase],by:m.phase===4?technicians.find(t=>t.id===m.technicianId)?.name:'مشرف الصيانة'});activity(messages[m.phase]+' '+m.id,m.unitId,'/maintenance/'+m.id,'wrench');return refreshWithToast(messages[m.phase]);}
 if(form.getAttribute('id')==='renew-form'){const c=data.contracts.find(c=>c.id===values.id);if(values.end<=c.end)return error('اختر تاريخاً بعد نهاية العقد الحالية.');c.end=values.end;c.status='ACTIVE';activity('تم تمديد العقد '+c.id,'تجربة تجديد العقد','/contracts/'+c.id,'calendar');return refreshWithToast('تم تمديد العقد ضمن العرض التجريبي.');}
 if(form.getAttribute('id')==='reset-form'){data=demoData();guide=-1;closeModal();go('/');render();toast('تمت إعادة بيانات العرض إلى البداية.');}
});
document.addEventListener('keydown',ev=>{
 if(ev.key==='Escape'){if(modalRoot.firstChild)closeModal();else perform('close-nav','',document.body);}
 if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(ev.target.tagName)&&!modalRoot.firstChild){ev.preventDefault();document.querySelector('#global-search input')?.focus();}
 if(ev.key==='Tab'&&modalRoot.firstChild){const focusables=[...modalRoot.querySelectorAll('button,a,input:not([type="hidden"]),select,textarea,[tabindex="0"]')].filter(el=>!el.disabled);const first=focusables[0],last=focusables.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last?.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first?.focus();}}
});
window.addEventListener('hashchange',()=>{clearTimeout(searchTimer);closeModal();render();window.scrollTo({top:0,behavior:'instant'});});
render();
